import collections
start,end=13283,32483
E=[e for e in events if start<=e[2]<=end]
def reach(delta, directed=True, src=1885, tgt=1460):
    # arr[node] = list of increasing arrival times (keep all, prune non-decreasing)
    arr=collections.defaultdict(list)
    arr[src]=[start]
    parent={}
    for u,v,t in E:
        pairs=[(u,v)] if directed else [(u,v),(v,u)]
        for a,b in pairs:
            L=arr.get(a)
            if not L: continue
            if a==src:
                ok=True; ta=start
            else:
                ta=None
                for x in L:
                    if x<=t: ta=x
                    else: break
                ok = ta is not None and t-ta<=delta
            if ok:
                Lb=arr[b]
                if not Lb or Lb[-1]<t:
                    Lb.append(t)
                    parent.setdefault((b,t),(a,ta))
    return arr,parent
